import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  Legend
} from "recharts";

const BpmChart = ({
  heartRateData,
  isAvgHovered,
  setIsAvgHovered,
  CustomLegend
}) => {
  return (
    <ResponsiveContainer>
      <ComposedChart
        data={heartRateData}
        margin={{ top: 20, right: 20, left: 0, bottom: 20 }}
      >
        <YAxis
  dataKey="value"
  axisLine={false}
  tickLine={false} // on désactive tout
  tick={(props) => {
    const { x, y, payload } = props
    const value = payload.value

    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10}
          dy={4}
          fill="#9b9eac"
          fontSize={12}
          textAnchor="end"
        >
          {value}
        </text>

        {value === 0 && (
          <line
            x1={0}
            x2={6}
            y1={0}
            y2={0}
            stroke="#ccc"
            strokeWidth={1}
          />
        )}
      </g>
    )
  }}
/>


        <YAxis
          tickLine={false}
          tick={{ fontSize: 11, dx: -10 }}
        />

        {/* Tooltip désactivé comme dans ton code */}
        <Tooltip wrapperStyle={{ display: "none" }} cursor={false} />

        {/* Barres min / max */}
        <Bar dataKey="min" barSize={14} fill="#fcc1b6" radius={[10, 10, 10, 10]} />
        <Bar dataKey="max" barSize={14} fill="#f4320b" radius={[10, 10, 10, 10]} />

        {/* Ligne moyenne */}
        <Line
          type="monotone"
          dataKey="avg"
          dot={{ r: 3, fill: "#0b23f4", stroke: "#0b23f4" }}
          stroke={isAvgHovered ? "#0b23f4" : "#b6bdfc"}
          strokeWidth={3}
          onMouseOver={() => setIsAvgHovered(true)}
          onMouseOut={() => setIsAvgHovered(false)}
          activeDot={false}
        />

        {/* Légende personnalisée */}
        <Legend content={<CustomLegend />} />
      </ComposedChart>
    </ResponsiveContainer>
  );
};

export default BpmChart;
